From 039def9e3898f81dfac6b7d1d1c8a07c87d3ad2b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 16:49:21 +0100
Subject: [PATCH] sm: Quit Chromium browsers as a whole at logout

Chromium-based browsers drop windows closed one by one at logout from
their session. A browser with several windows is now left open until
the logout can't be cancelled, then asked to quit with SIGTERM.

BUG: 511236
---
 src/sm.cpp | 119 ++++++++++++++++++++++++++++++++++++++---------------
 src/sm.h   |   2 +
 2 files changed, 87 insertions(+), 34 deletions(-)

diff --git a/src/sm.cpp b/src/sm.cpp
index 7a4591880a..c34647ba7f 100644
--- a/src/sm.cpp
+++ b/src/sm.cpp
@@ -10,12 +10,15 @@

 #include "sm.h"

+#include <csignal>
 #include <cstdlib>
 #include <kconfig.h>
 #include <pwd.h>
 #include <unistd.h>

 #include "virtualdesktops.h"
+#include "wayland/clientconnection.h"
+#include "wayland/surface.h"
 #include "wayland_server.h"
 #include "workspace.h"
 #include "xdgshellwindow.h"
@@ -24,11 +27,12 @@
 #include "x11window.h"
 #endif

+#include <KService>
+#include <QFile>
 #include <QSessionManager>
 #if KWIN_BUILD_NOTIFICATIONS
 #include <KLocalizedString>
 #include <KNotification>
-#include <KService>
 #endif

 #include "sessionadaptor.h"
@@ -364,6 +368,16 @@ void SessionManager::finishSaveSession(const QString &name)
     storeSession(name, SMSavePhase2);
 }

+static bool isChromiumBrowser(const XdgToplevelWindow *window)
+{
+    const auto service = KService::serviceByDesktopName(window->desktopFileName());
+    if (!service || !service->categories().contains(u"WebBrowser"_s)) {
+        return false;
+    }
+    QFile maps(u"/proc/%1/maps"_s.arg(window->pid()));
+    return maps.open(QIODevice::ReadOnly) && maps.readAll().contains("/resources.pak\n");
+}
+
 bool SessionManager::closeWaylandWindows()
 {
     Q_ASSERT(calledFromDBus());
@@ -379,36 +393,45 @@ bool SessionManager::closeWaylandWindows()
     auto dbusMessage = message();
     setDelayedReply(true);

-    const auto windows = workspace()->windows();
-    m_pendingWindows.clear();
-    m_pendingWindows.reserve(windows.size());
-    for (const auto window : windows) {
+    QList<XdgToplevelWindow *> toplevelWindows;
+    QHash<ClientConnection *, int> windowCounts;
+    for (const auto window : workspace()->windows()) {
         if (auto toplevelWindow = qobject_cast<XdgToplevelWindow *>(window)) {
-            connect(toplevelWindow, &XdgToplevelWindow::closed, m_closingWindowsGuard.get(), [this, toplevelWindow, dbusMessage] {
-                m_pendingWindows.removeOne(toplevelWindow);
-                if (m_pendingWindows.empty()) {
-#if KWIN_BUILD_NOTIFICATIONS
-                    if (m_cancelNotification) {
-                        m_cancelNotification->close();
-                        m_cancelNotification = nullptr;
-                    }
-#endif
-                    m_closeTimer.stop();
-                    m_logoutAnywayTimer.stop();
-                    m_closingWindowsGuard.reset();
-                    QDBusConnection::sessionBus().send(dbusMessage.createReply(true));
-                } else {
-                    updateWaylandCancelNotification();
-                }
-            });
+            toplevelWindows.push_back(toplevelWindow);
+            windowCounts[toplevelWindow->surface()->client()]++;
+        }
+    }
+
+    // Chromium-based browsers drop every window closed while others are still open from their session, so
+    // a browser with several windows is left alone until the logout can't be cancelled and then asked to quit.
+    QHash<ClientConnection *, bool> quitClients;
+    m_pendingWindows.clear();
+    m_quitWindows.clear();
+    for (const auto toplevelWindow : std::as_const(toplevelWindows)) {
+        connect(toplevelWindow, &XdgToplevelWindow::closed, m_closingWindowsGuard.get(), [this, toplevelWindow, dbusMessage] {
+            m_quitWindows.removeOne(toplevelWindow);
+            m_pendingWindows.removeOne(toplevelWindow);
+            if (m_pendingWindows.empty()) {
+                finishClosingWaylandWindows(dbusMessage, true);
+            } else {
+                updateWaylandCancelNotification();
+            }
+        });
+        ClientConnection *client = toplevelWindow->surface()->client();
+        auto quitClient = quitClients.find(client);
+        if (quitClient == quitClients.end()) {
+            quitClient = quitClients.insert(client, windowCounts[client] > 1 && isChromiumBrowser(toplevelWindow));
+        }
+        if (*quitClient) {
+            m_quitWindows.push_back(toplevelWindow);
+        } else {
             m_pendingWindows.push_back(toplevelWindow);
             toplevelWindow->closeWindow();
         }
     }

     if (m_pendingWindows.empty()) {
-        m_closingWindowsGuard.reset();
-        QDBusConnection::sessionBus().send(dbusMessage.createReply(true));
+        finishClosingWaylandWindows(dbusMessage, true);
         return true;
     }

@@ -421,21 +444,17 @@ bool SessionManager::closeWaylandWindows()
         auto cancel = m_cancelNotification->addAction(i18nc("@action:button", "Cancel Logout"));
         auto quit = m_cancelNotification->addAction(i18nc("@action::button", "Log Out Anyway"));
         connect(cancel, &KNotificationAction::activated, m_closingWindowsGuard.get(), [dbusMessage, this] {
-            m_closingWindowsGuard.reset();
-            QDBusConnection::sessionBus().send(dbusMessage.createReply(false));
+            finishClosingWaylandWindows(dbusMessage, false);
         });
         connect(quit, &KNotificationAction::activated, m_closingWindowsGuard.get(), [dbusMessage, this] {
-            m_closingWindowsGuard.reset();
-            QDBusConnection::sessionBus().send(dbusMessage.createReply(true));
+            finishClosingWaylandWindows(dbusMessage, true);
         });
         connect(m_cancelNotification, &KNotification::closed, m_closingWindowsGuard.get(), [dbusMessage, this] {
-            m_closingWindowsGuard.reset();
-            QDBusConnection::sessionBus().send(dbusMessage.createReply(false));
+            finishClosingWaylandWindows(dbusMessage, false);
         });
         m_cancelNotification->sendEvent();
 #else
-        m_closingWindowsGuard.reset();
-        QDBusConnection::sessionBus().send(dbusMessage.createReply(false));
+        finishClosingWaylandWindows(dbusMessage, false);
 #endif
     });

@@ -443,12 +462,44 @@ bool SessionManager::closeWaylandWindows()
     m_logoutAnywayTimer.setSingleShot(true);
     connect(&m_logoutAnywayTimer, &QTimer::timeout, m_closingWindowsGuard.get(), [this, dbusMessage] {
         qCInfo(KWIN_CORE) << "Not all windows have closed, logging out anyway";
-        m_closingWindowsGuard.reset();
-        QDBusConnection::sessionBus().send(dbusMessage.createReply(true));
+        finishClosingWaylandWindows(dbusMessage, true);
     });
     return true;
 }

+void SessionManager::finishClosingWaylandWindows(const QDBusMessage &dbusMessage, bool logout)
+{
+#if KWIN_BUILD_NOTIFICATIONS
+    if (m_cancelNotification) {
+        disconnect(m_cancelNotification, nullptr, m_closingWindowsGuard.get(), nullptr);
+        m_cancelNotification->close();
+        m_cancelNotification = nullptr;
+    }
+#endif
+    m_closeTimer.stop();
+    m_logoutAnywayTimer.stop();
+
+    if (logout && !m_quitWindows.empty()) {
+        QSet<pid_t> pids;
+        for (const auto window : std::as_const(m_quitWindows)) {
+            pids.insert(window->pid());
+        }
+        for (const pid_t pid : std::as_const(pids)) {
+            if (pid > 0 && pid != getpid()) {
+                ::kill(pid, SIGTERM);
+            }
+        }
+        m_pendingWindows = std::exchange(m_quitWindows, {});
+        QTimer::singleShot(std::chrono::seconds(10), m_closingWindowsGuard.get(), [this, dbusMessage] {
+            finishClosingWaylandWindows(dbusMessage, true);
+        });
+        return;
+    }
+
+    m_closingWindowsGuard.reset();
+    QDBusConnection::sessionBus().send(dbusMessage.createReply(logout));
+}
+
 void SessionManager::updateWaylandCancelNotification()
 {
 #if KWIN_BUILD_NOTIFICATIONS
diff --git a/src/sm.h b/src/sm.h
index 693082ebff..1f2cc36e29 100644
--- a/src/sm.h
+++ b/src/sm.h
@@ -77,6 +77,7 @@ private:
     void addSessionInfo(KConfigGroup &cg);

     void updateWaylandCancelNotification();
+    void finishClosingWaylandWindows(const QDBusMessage &dbusMessage, bool logout);

     SessionState m_sessionState = SessionState::Normal;

@@ -85,6 +86,7 @@ private:

     QList<SessionInfo> session;
     QList<XdgToplevelWindow *> m_pendingWindows;
+    QList<XdgToplevelWindow *> m_quitWindows;
     QTimer m_closeTimer;
     QTimer m_logoutAnywayTimer;
     std::unique_ptr<QObject> m_closingWindowsGuard;
